def classify(score):
if not 0 <= score <= 10:
raise ValueError("Điểm phải từ 0 đến 10")
if score >= 8.5:
return "Tốt"
if score >= 7:
return "Khá"
if score >= 5:
return "Đạt"
return "Cần ôn"
assert classify(5) == "Đạt"
assert classify(8.5) == "Tốt"
